export type ArtName = keyof typeof ART;

/**
 * Avatar frames. The art is the project owner's own work (see
 * `assets/media/README.md`); `halo` is the animated one.
 */
const FRAMES: Record<AvatarFrameKey, number> = {
  blossom: require('../../../assets/media/frames/blossom.png'),
  wings: require('../../../assets/media/frames/wings.png'),
  heart: require('../../../assets/media/frames/heart.png'),
  rope: require('../../../assets/media/frames/rope.png'),
  halo: require('../../../assets/media/frames/halo.webp'),
};

/**
 * How each frame sits around the photo.
 *
 * Every frame is a square canvas with a transparent hole, but the hole is not
 * always centred: the heart and the blossoms hang off the bottom of the ring, so
 * the opening sits above the canvas centre. Drawing the art centred on the photo
 * would leave a gap under the chin and clip the hair, so each frame carries the
 * offset of its hole as well as its size.
 *
 * `scale` is (canvas side ÷ hole diameter) and both offsets are fractions of the
 * canvas side. They are measured once from the art's alpha channel — the hole's
 * horizontal extremes give its centre and diameter, the first transparent row
 * gives its top.
 */
export interface AvatarFrameFit {
  scale: number;
  offsetX: number;
  offsetY: number;
}

export const AVATAR_FRAME_FIT: Record<AvatarFrameKey, AvatarFrameFit> = {
  blossom: { scale: 1.323, offsetX: 0.0098, offsetY: -0.0303 },
  wings: { scale: 1.463, offsetX: 0, offsetY: -0.0312 },
  heart: { scale: 1.34, offsetX: 0, offsetY: -0.0469 },
  rope: { scale: 1.219, offsetX: 0, offsetY: 0 },
  halo: { scale: 1.905, offsetX: 0, offsetY: 0 },
};

export const AVATAR_FRAME_KEYS = Object.keys(FRAMES) as AvatarFrameKey[];

export function frameSource(key: AvatarFrameKey): number {
  return FRAMES[key];
}

const HONOR_PANEL: Record<HonorWall['key'], { light: number; dark: number }> = {
  badges: { light: ART.honorPanelBadges, dark: ART.honorPanelBadgesDark },
  titles: { light: ART.honorPanelTitles, dark: ART.honorPanelTitlesDark },
  gifts: { light: ART.honorPanelGifts, dark: ART.honorPanelGiftsDark },
};

/** The plate behind one honour wall, in the active scheme. */
export function honorPanelSource(tone: HonorWall['key'], dark: boolean): number {
  return HONOR_PANEL[tone][dark ? 'dark' : 'light'];
}

/** The ring a badge medallion sits in. */
export function honorMedalSource(dark: boolean): number {
  return dark ? ART.honorMedalDark : ART.honorMedal;
}

/** The plaque a gift's glyph is framed by. */
export function honorGiftFrameSource(dark: boolean): number {
  return dark ? ART.honorGiftFrameDark : ART.honorGiftFrame;
}

export type MediaFolder = 'portraits' | 'covers' | 'posts' | 'rooms' | 'backgrounds';

/**
 * Resolves an image reference to something `expo-image` can render: a bundled
 * asset id for registry entries, a remote source for anything else.
 */
export function imageSource(ref?: string): ImageSource | number | undefined {
  if (!ref) {
    return undefined;
  }
  return IMAGES[ref] ?? { uri: ref };
}

/**
 * Builds the reference a fixture stores. Keeps the scheme in one place.
 * Portraits, covers, posts and rooms are JPGs; backdrops keep their PNG.
 */
export function mediaRef(folder: MediaFolder, name: string, extension = 'jpg'): string {
  return `asset:media/${folder}/${name}.${extension}`;
}

export function artSource(name: ArtName): number {
  return ART[name];
}
